+using System.Text.Json;
+using Microsoft.EntityFrameworkCore;
+using RecipeApi.Infrastructure;
+using RecipeApi.Models;
+
+namespace RecipeApi.Services;
+
+public sealed partial class RecipeFilePublicationStore
+{
+    private async Task ValidateUrlRepairFollowupAsync(WorkflowInstance workflow, WorkflowTask task, Guid recipeId, CancellationToken ct)
+    {
+        workflow = await db.WorkflowInstances.AsNoTracking().Include(x => x.Tasks).SingleAsync(x => x.Id == workflow.Id, ct);
+        ValidateExecutionLaunch(workflow);
+        if (workflow.WorkflowId != "url-import" || workflow.RecipePublicationCapture is null
+            || task.ProcessorName is not ("GenerateHero" or "CategorizeRecipe"))
+            throw new InvalidDataException("URL repair follow-up requires its original workflow task.");
+        var launch = ReadRecoveryJson<Launch>(workflow.RecipePublicationCapture);
+        var extraction = workflow.Tasks.SingleOrDefault(x => x.ProcessorName == "ExtractRecipe");
+        var visited = new HashSet<string>(StringComparer.Ordinal);
+        bool HasAncestor(string name)
+        {
+            if (!visited.Add(name)) return false;
+            var inputs = launch.Tasks.Values.Where(x => x.Name == name).ToArray();
+            return inputs.Length == 1 && (extraction?.TaskName == name || inputs[0].DependsOn.Any(HasAncestor));
+        }
+        if (launch.Capture.RecipeId != recipeId || extraction is null
+            || !launch.Tasks.TryGetValue(task.TaskId, out var original) || original.Processor != task.ProcessorName
+            || original.Payload != CanonicalRecipeContentStore.NormalizeJson(task.Payload) || !original.DependsOn.Any(HasAncestor))
+            throw new InvalidDataException("URL repair follow-up has no captured extraction ancestor.");
+        var publication = await db.RecipeFilePublications.AsNoTracking()
+            .SingleOrDefaultAsync(x => x.RecipeId == recipeId && x.OperationId == extraction.TaskId, ct);
+        if (publication is null || !publication.Delivered)
+            throw new InvalidDataException("URL repair follow-up requires delivered ingredient repair.");
+        var envelope = ReadEnvelope(publication);
+        if (envelope.Candidate.SourceKind != "url-ingredient-repair"
+            || !await CanRepairCanonicalUrlIngredientsAsync(envelope.Capture, extraction.TaskId, ct))
+            throw new InvalidDataException("URL repair follow-up requires its original accepted report and fetched source ancestor.");
+    }
+
+    private async Task<(WorkflowInstance Workflow, Launch Launch, WorkflowTask Task)?> AcceptedUrlIngredientRepairAsync(
+        RecipePublicationCapture capture, Guid operationId, string processor, CancellationToken ct)
+    {
+        if (capture.FieldHashVersion != 4 || capture.Fields?.CanonicalContent is null || capture.Fields.RawMetadata is null
+            || string.IsNullOrWhiteSpace(capture.Fields.SourceUrl) || capture.Files.GetValueOrDefault("original/source.pdf") is not null)
+            return null;
+        var task = await db.WorkflowTasks.AsNoTracking().SingleOrDefaultAsync(x => x.TaskId == operationId, ct);
+        if (task is null || task.InstanceId == Guid.Empty || task.ProcessorName != processor) return null;
+        var workflow = await db.WorkflowInstances.AsNoTracking().Include(x => x.Tasks).SingleOrDefaultAsync(x => x.Id == task.InstanceId, ct);
+        var report = await db.RecipeImportReports.AsNoTracking().SingleOrDefaultAsync(x => x.RecipeId == capture.RecipeId, ct);
+        if (workflow is null || workflow.WorkflowId != "url-import" || workflow.RecipePublicationCapture is null
+            || report?.RepairIntentId is not Guid intentId || report.LastWorkflowInstanceId != workflow.Id
+            || report.Status != RecipeImportReportStatus.Reimporting || !report.Reasons.SequenceEqual(["ingredients"])
+            || string.IsNullOrWhiteSpace(report.Note)) return null;
+        var intent = await db.RecipeRepairIntents.AsNoTracking().SingleOrDefaultAsync(x => x.Id == intentId, ct)
+            ?? throw new InvalidDataException("Accepted URL ingredient repair command is missing.");
+        RecipeReportRepairIntent.ValidateAccepted(intent, workflow);
+        var command = RecipeReportRepairIntent.Read(intent);
+        if (!command.Parameters.TryGetValue("repairReasons", out var reasons) || reasons != string.Join(',', report.Reasons)
+            || !command.Parameters.TryGetValue("repairNote", out var note) || note != report.Note
+            || !command.Parameters.TryGetValue("url", out var url) || url != capture.Fields.SourceUrl) return null;
+        var launch = ReadRecoveryJson<Launch>(workflow.RecipePublicationCapture);
+        if (launch.Capture.RecipeId != capture.RecipeId || launch.Capture.FieldHashVersion != 4
+            || launch.Capture.FieldHash != capture.FieldHash || launch.Capture.SourceRevision != capture.SourceRevision
+            || launch.Capture.ContentRevision != capture.ContentRevision || Hash(launch.Capture.FoodAuthority!) != Hash(capture.FoodAuthority!)
+            || !launch.Tasks.TryGetValue(operationId, out var original) || original.Processor != processor
+            || original.Payload != CanonicalRecipeContentStore.NormalizeJson(task.Payload)) return null;
+        return (workflow, launch, task);
+    }
+
+    internal async Task<bool> CanRepairCanonicalUrlSourceAsync(RecipePublicationCapture capture, Guid operationId, CancellationToken ct)
+    {
+        var accepted = await AcceptedUrlIngredientRepairAsync(capture, operationId, "FetchUrlContent", ct);
+        if (accepted is null || !SameFiles(accepted.Value.Launch.Capture.Files, capture.Files)) return false;
+        using var input = JsonDocument.Parse(accepted.Value.Task.Payload!);
+        return input.RootElement.TryGetProperty("url", out var url) && url.GetString() == capture.Fields!.SourceUrl;
+    }
+
+    internal async Task<bool> CanRepairCanonicalUrlIngredientsAsync(RecipePublicationCapture capture, Guid operationId, CancellationToken ct)
+    {
+        var accepted = await AcceptedUrlIngredientRepairAsync(capture, operationId, "ExtractRecipe", ct);
+        if (accepted is null) return false;
+        var launch = accepted.Value.Launch;
+        var ancestors = new HashSet<Guid>();
+        var visiting = new HashSet<Guid>();
+        void Visit(Guid id)
+        {
+            if (ancestors.Contains(id)) return;
+            if (!visiting.Add(id)) throw new InvalidDataException("URL repair source dependency cycle.");
+            foreach (var name in launch.Tasks[id].DependsOn)
+            {
+                var inputs = launch.Tasks.Where(x => x.Value.Name == name).ToArray();
+                if (inputs.Length != 1) throw new InvalidDataException("URL repair source dependency is ambiguous.");
+                Visit(inputs[0].Key);
+            }
+            visiting.Remove(id);
+            if (id != operationId) ancestors.Add(id);
+        }
+        Visit(operationId);
+        var fetches = ancestors.Where(id => launch.Tasks[id].Processor == "FetchUrlContent").ToArray();
+        if (fetches.Length != 1) return false;
+        var fetchId = fetches[0];
+        var publication = await db.RecipeFilePublications.AsNoTracking()
+            .SingleOrDefaultAsync(x => x.RecipeId == capture.RecipeId && x.OperationId == fetchId, ct);
+        if (publication is null || !publication.Delivered) return false;
+        var source = ReadEnvelope(publication);
+        if (source.Candidate.SourceKind != "url-repair-source"
+            || source.Candidate.ProducerInput != "FetchUrlContent\n" + launch.Tasks[fetchId].Payload
+            || publication.ResultHash != capture.FieldHash
+            || !await CanRepairCanonicalUrlSourceAsync(source.Capture, fetchId, ct)) return false;
+        var files = launch.Capture.Files.ToDictionary(x => x.Key, x => x.Value, StringComparer.Ordinal);
+        foreach (var (path, bytes) in source.Output) files[path] = bytes;
+        return SameFiles(files, capture.Files);
+    }
+
+    internal FoodMappingPreparation PrepareUrlIngredientRepair(RecipePublicationCapture capture, string raw, Guid operationId,
+        string? revision = null)
+    {
+        ValidateOriginalFields(capture);
+        // Reuse the same pure conservative ingredient merge. Source and report
+        // admission remain separate from the photo workflow's authority.
+        var prepared = CanonicalRecipeContentStore.PreparePhotoIngredientRepair(capture.Fields!, raw, revision ?? Guid.NewGuid().ToString("N"));
+        var prior = CanonicalRecipeContentStore.Read(RestoreV4(capture))!;
+        return FoodMappingQualification.PrepareCapturedUrlRepair(prepared, capture.FoodAuthority!, operationId, prior,
+            capture.FoodEvidence!.Value, capture.Fields!.SourceUrl!);
+    }
+
+    private static IReadOnlyDictionary<string, byte[]?> PrepareUrlIngredientRepair(RecipePublicationCapture capture,
+        RecipePublicationCandidate candidate, Guid operationId)
+    {
+        if (capture.FieldHashVersion != 4 || candidate.RecipeJson is null || capture.Fields?.CanonicalContent is null
+            || string.IsNullOrWhiteSpace(capture.Fields.SourceUrl) || capture.Files.GetValueOrDefault("original/source.pdf") is not null
+            || candidate.SourceFiles is not null || candidate.SourceContext is not null || candidate.BootstrapIntent is not null
+            || candidate.FollowupIntent is not null || candidate.ReviewReasons is not null || operationId == Guid.Empty
+            || capture.Files.GetValueOrDefault("recipe.info") is not { } infoBytes)
+            throw new InvalidDataException("URL ingredient repair requires captured canonical facts and no media selection.");
+        var info = JsonSerializer.Deserialize<RecipeInfo>(infoBytes, Json)!;
+        if (Hash(info) != Hash(candidate.Info)) throw new InvalidDataException("URL ingredient repair cannot replace captured metadata.");
+        using var document = JsonDocument.Parse(candidate.RecipeJson);
+        var incoming = RecipeExportContent.ReadCurrent(document.RootElement, capture.RecipeId);
+        var prepared = CanonicalRecipeContentStore.PreparePhotoIngredientRepair(capture.Fields,
+            incoming.RawMetadata ?? throw new InvalidDataException("URL repair has no normalized source."), incoming.Content.ContentRevision);
+        var prior = CanonicalRecipeContentStore.Read(RestoreV4(capture))!;
+        var mapped = FoodMappingQualification.PrepareCapturedUrlRepair(prepared, capture.FoodAuthority!, operationId, prior,
+            capture.FoodEvidence!.Value, capture.Fields.SourceUrl);
+        if (!RecipeExportContent.IsIdenticalCurrent(incoming, mapped.Export)
+            || CanonicalRecipeContentStore.NormalizeJson(candidate.MappingEvidence) != CanonicalRecipeContentStore.NormalizeJson(mapped.Evidence))
+            throw new InvalidDataException("URL ingredient repair differs from its captured protected merge.");
+        return new Dictionary<string, byte[]?> { ["recipe.json"] = System.Text.Encoding.UTF8.GetBytes(candidate.RecipeJson) };
+    }
+
+    private static IReadOnlyDictionary<string, byte[]?> PrepareUrlRepairSource(RecipePublicationCapture capture, RecipePublicationCandidate candidate)
+    {
+        if (capture.FieldHashVersion != 4 || capture.Fields?.CanonicalContent is null || string.IsNullOrWhiteSpace(capture.Fields.SourceUrl)
+            || capture.Files.GetValueOrDefault("original/source.pdf") is not null
+            || candidate.RecipeJson is not null || candidate.SourceFiles is not { Count: 1 } source
+            || source.GetValueOrDefault("original/content.html") is not { Length: > 0 } html
+            || string.IsNullOrWhiteSpace(System.Text.Encoding.UTF8.GetString(html))
+            || candidate.SourceContext is not null || candidate.BootstrapIntent is not null || candidate.FollowupIntent is not null
+            || candidate.ReviewReasons is not null || candidate.MappingEvidence is not null
+            || capture.Files.GetValueOrDefault("recipe.info") is not { } info)
+            throw new InvalidDataException("URL repair source selects one nonempty fetched page and no content, metadata or media replacement.");
+        if (Hash(JsonSerializer.Deserialize<RecipeInfo>(info, Json)!) != Hash(candidate.Info))
+            throw new InvalidDataException("URL repair source cannot replace captured private metadata.");
+        return new Dictionary<string, byte[]?> { ["original/content.html"] = html };
+    }
+}
