+        supply = new[] { new { name = "pasta", requiredQuantity = new { value = amount, unitText = "g" } } },
+        recipeInstructions = new[] { new { name = "Cook", itemListElement = new[] { new { text = "Cook the pasta gently." } } } }
+    });
+
+    private sealed class PageHandler : HttpMessageHandler
+    {
+        public int Calls { get; private set; }
+        public HttpStatusCode Status { get; set; } = HttpStatusCode.OK;
+        public Func<Task>? OnFetch { get; set; }
+        public string Page { get; set; } = "<html><body><h1>Source title</h1><p>200 g pasta</p></body></html>";
+        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
+        {
+            Calls++;
+            if (OnFetch is not null) await OnFetch();
+            return new HttpResponseMessage(Status) { Content = new StringContent(Page) };
+        }
+    }
+}
